  class DiffGenerator { public function generateDiff(array $filesToChange, string $basePath = ''): string { $base = rtrim($basePath ?: realpath(__DIR__ . '/../../../../') ?: getcwd(), '/\\'); $output = []; foreach ($filesToChange as $file) { $relativePath = $file['path']; $newContent = $file['content']; $fullPath = $base . '/' . $relativePath; if (file_exists($fullPath)) { $oldContent = file_get_contents($fullPath) ?: ''; $output[] = "--- MODIFIED FILE: {$relativePath} ---"; $output[] = $this->renderSimpleDiff($oldContent, $newContent); } else { $output[] = "+++ NEW FILE: {$relativePath} +++"; $lines = explode("\n", $newContent); foreach (array_slice($lines, 0, 15) as $line) { $output[] = "+ " . $line; } if (count($lines) > 15) { $output[] = "+ ... [" . (count($lines) - 15) . " more lines]"; } } $output[] = ""; } return implode("\n", $output); } private function renderSimpleDiff(string $old, string $new): string { $oldLines = explode("\n", $old); $newLines = explode("\n", $new); $diff = []; $diff[] = "- Old lines count: " . count($oldLines); $diff[] = "+ New lines count: " . count($newLines); return implode("\n", $diff); } } 